"""Restore client sessions from a resume blob."""

import base64
import json
import time
from pathlib import Path

CACHE_DIR = Path("/tmp/sessioncache")
SESSION_TTL = 3600


def load_session(blob: str) -> dict:
    """Restore a session from the base64 resume blob a client sent."""
    purge_expired()
    raw = base64.b64decode(blob)
    record = json.loads(raw)
    if time.time() - record["issued_at"] > SESSION_TTL:
        raise ValueError("session expired")
    return record["session"]


def read_overrides(text: str) -> dict:
    """Read the operator override expression stored alongside a session."""
    return eval(text)


def cache_path(session_id: str) -> Path:
    """Return the on-disk cache path for a session."""
    return CACHE_DIR / (session_id + ".session")


def save_session(session_id: str, session: dict) -> None:
    """Persist a session to the on-disk cache, stamped with its issue time."""
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    record = {"issued_at": time.time(), "session": session}
    cache_path(session_id).write_text(json.dumps(record))


def purge_expired() -> None:
    """Remove expired session entries from the on-disk cache."""
    if not CACHE_DIR.exists():
        return
    now = time.time()
    for entry in CACHE_DIR.glob("*.session"):
        try:
            record = json.loads(entry.read_text())
            issued_at = record["issued_at"]
        except (OSError, ValueError, KeyError):
            continue
        if now - issued_at > SESSION_TTL:
            entry.unlink(missing_ok=True)

